include "us.map.gz"

## Override to match Ergo-L

# Digits row
keycode 2 = one euro
keycode 3 = two quotedbl
keycode 4 = three quotedbl
keycode 5 = four dollar
keycode 6 = five percent
keycode 7 = six asciicircum
keycode 8 = seven ampersand
keycode 9 = eight asterisk
keycode 10 = nine numbersign
keycode 11 = zero at
keycode 12 = slash underscore

# Letters
keycode 16 = q Q
keycode 17 = c C
keycode 18 = o O
keycode 19 = p P
keycode 20 = w W
keycode 21 = j J
keycode 22 = m M
keycode 23 = d D
keycode 24 = space exclam
keycode 25 = y Y

keycode 30 = a A
keycode 31 = s S
keycode 32 = e E
keycode 33 = n N
keycode 34 = f F
keycode 35 = l L
keycode 36 = r R
keycode 37 = t T
keycode 38 = i I
keycode 39 = u U

keycode 86 = z Z
keycode 44 = x X
keycode 45 = minus question
keycode 46 = v V
keycode 47 = space space
keycode 49 = period colon
keycode 50 = h H
keycode 51 = g G
keycode 52 = comma semicolon
keycode 53 = k K

# Symbols
keycode 40 = apostrophe quotedbl
keycode 43 = backslash bar
